import heapq

def solve():
    t = int(input())  # 测试数据组数
    for _ in range(t):
        n = int(input())  # 学习计划长度
        a = list(map(int, input().split()))  # 学习计划

        mem = {}  # 存储记忆值
        cnt = {}  # 存储学习次数
        pq = []   # 小根堆
        active = max_active = 0  # 当前活跃和最大活跃汉字数量
        time = 0  # 当前时间步

        for char in a:
            time += 1  # 学习步数

            # 清理已遗忘的汉字
            while pq and pq[0][0] == time:
                d, ch = heapq.heappop(pq)
                if mem.get(ch) == d:
                    del mem[ch]
                    active -= 1

            # 更新当前汉字的记忆值
            k = cnt.get(char, 0) + 1
            nxt = k * k
            if char in mem:
                mem[char] += nxt
            else:
                active += 1
                mem[char] = time + nxt

            cnt[char] = k
            heapq.heappush(pq, (mem[char], char))

            # 更新最大活跃汉字数量
            max_active = max(max_active, active)

        print(max_active)

if __name__ == "__main__":
    solve()
```

