### Python

```python
import sys
import heapq

def solve() -> None:
    input_data = sys.stdin.read().split()
    it = iter(input_data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        # 读取核心类型序列
        cores = [int(next(it)) for _ in range(n)]

        expire = {}          # 记录当前激活类型的衰减截止时间
        cnt = {}             # 记录每种类型的累计出现次数
        pq = []              # 小根堆，存储 (截止时间, 类型)
        active = 0
        max_active = 0
        time = 0

        for c in cores:
            time += 1

            # 移除刚好在当前时刻衰减到0的类型
            while pq and pq[0][0] == time:
                et, typ = heapq.heappop(pq)
                if expire.get(typ) == et:
                    del expire[typ]
                    active -= 1

            # 更新当前类型的出现次数
            k = cnt.get(c, 0) + 1
            cnt[c] = k
            delta = k * k

            if c in expire:
                # 原本处于激活状态，直接累加能量
                expire[c] += delta
            else:
                # 原本未激活，重新激活
                expire[c] = time + delta
                active += 1

            heapq.heappush(pq, (expire[c], c))

            if active > max_active:
                max_active = active

        out_lines.append(str(max_active))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

